10	#ifndef UT_TEST
11	#include <pthread.h>
12	#include <semaphore.h>
13	#include <stdlib.h>
14	
15	#include "securec.h"
16	
17	#include "prof_communication.h"
18	#include "prof_h2d_kernel_msg.h"
19	#include "prof_hdc_comm.h"
20	#include "prof_hdc.h"
21	
22	#define PROF_HDC_FLUSH_MAXTIME 20 /* s */
23	#define PROF_HDC_RESPOND_MAXTIME 10 /* s */
24	#define PROF_HDC_SESSION_CLOSE_MAXTIME 50 /* s */
25	#define PROF_HDC_TRY_COUNT 60000
26	#define PROF_HDC_TRY_WAIT_TIME 1000 /* us */
27	#define PROF_HDC_GET_CHANNELS_IDLE 0
28	#define PROF_HDC_GET_CHANNELS_OCCUPY 1
29	
30	struct prof_hdc_info {
31	    pthread_mutex_t mutex;
32	    uint32_t verify;
33	    struct prof_channel_list *channels;
34	    sem_t sem;
35	    int status;
36	};
37	
38	static struct prof_hdc_info g_prof_hdc_info[DEV_NUM];
39	
40	STATIC void prof_hdc_info_init(uint32_t dev_id)
41	{
42	    struct prof_hdc_info *info = &g_prof_hdc_info[dev_id];
43	
44	    (void)pthread_mutex_init(&info->mutex, NULL);
45	    info->verify = 0;
46	    info->channels = NULL;
47	    ATOMIC_SET(&info->status, PROF_HDC_GET_CHANNELS_IDLE);
48	    (void)sem_init(&info->sem, 0, 0);
49	}
50	
51	STATIC struct prof_hdc_info *prof_hdc_get_info(uint32_t dev_id)
52	{
53	    static pthread_mutex_t init_mutex = PTHREAD_MUTEX_INITIALIZER;
54	    static int init_flag[DEV_NUM] = {0};
55	
56	    if (init_flag[dev_id] != 0) {
57	        return &g_prof_hdc_info[dev_id];
58	    }
59	
60	    (void)pthread_mutex_lock(&init_mutex);
61	    if (init_flag[dev_id] == 0) {
62	        prof_hdc_info_init(dev_id);
63	        ATOMIC_SET(&init_flag[dev_id], 1);
64	    }
65	    (void)pthread_mutex_unlock(&init_mutex);
66	
67	    return &g_prof_hdc_info[dev_id];
68	}
69	
70	struct prof_hdc_chan_info {
71	    int ret_val;
72	    sem_t sem;
73	};
74	
75	static struct prof_hdc_chan_info *g_prof_hdc_chan[DEV_NUM] = {NULL};
76	
77	STATIC drvError_t prof_hdc_chan_info_init(uint32_t dev_id)
78	{
79	    struct prof_hdc_chan_info *chan_info = NULL;
80	    int i;
81	
82	    chan_info = (struct prof_hdc_chan_info *)calloc(PROF_CHANNEL_NUM_MAX, sizeof(*chan_info));
83	    if (chan_info == NULL) {
84	        PROF_ERR("Failed to alloc hdc_chan_info. (dev_id=%u)\n", dev_id);
85	        return DRV_ERROR_MALLOC_FAIL;
86	    }
87	
88	    for (i = 0; i < PROF_CHANNEL_NUM_MAX; i++) {
89	        (void)sem_init(&chan_info[i].sem, 0, 0);
90	    }
91	
92	    g_prof_hdc_chan[dev_id] = chan_info;
93	    return DRV_ERROR_NONE;
94	}
95	
96	STATIC struct prof_hdc_chan_info *prof_hdc_get_chan_info(uint32_t dev_id, uint32_t chan_id)
97	{
98	    static pthread_mutex_t init_mutex = PTHREAD_MUTEX_INITIALIZER;
99	    static int init_flag[DEV_NUM] = {0};
100	    drvError_t ret;
101	
102	    if (init_flag[dev_id] != 0) {
103	        return &g_prof_hdc_chan[dev_id][chan_id];
104	    }
105	
106	    (void)pthread_mutex_lock(&init_mutex);
107	    if (init_flag[dev_id] == 0) {
108	        ret = prof_hdc_chan_info_init(dev_id);
109	        if (ret != DRV_ERROR_NONE) {
110	            (void)pthread_mutex_unlock(&init_mutex);
111	            PROF_ERR("Failed to init hdc_chan_info. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
112	            return NULL;
113	        }
114	
115	        ATOMIC_SET(&init_flag[dev_id], 1);
116	    }
117	    (void)pthread_mutex_unlock(&init_mutex);
118	
119	    return &g_prof_hdc_chan[dev_id][chan_id];
120	}
121	
122	STATIC drvError_t prof_hdc_chan_sem_init(uint32_t dev_id, uint32_t chan_id)
123	{
124	    struct prof_hdc_chan_info *chan_info = prof_hdc_get_chan_info(dev_id, chan_id);
125	
126	    if (chan_info == NULL) {
127	        PROF_ERR("Failed to get hdc_chan_info. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
128	        return DRV_ERROR_MALLOC_FAIL;
129	    }
130	
131	    (void)sem_init(&chan_info->sem, 0, 0);
132	    return DRV_ERROR_NONE;
133	}
134	
135	STATIC drvError_t prof_hdc_get_ret(uint32_t dev_id, uint32_t chan_id, int timeout, uint32_t msg_type)
136	{
137	    sem_t *sem = NULL;
138	    uint32_t wait_count = 0;
139	    uint32_t wait_count_max = (uint32_t)(timeout * 1000000 / 500);
140	    int ret;
141	    drvError_t drv_ret;
142	
143	    if (msg_type == PROF_HDC_CMD_GET_CHANNEL) {
144	        sem = &(prof_hdc_get_info(dev_id)->sem);
145	    } else {
146	        sem = &(prof_hdc_get_chan_info(dev_id, chan_id)->sem);
147	    }
148	
149	    ret = sem_trywait(sem);
150	    while (ret != 0) {
151	        if (wait_count == wait_count_max) {
152	            PROF_ERR("Waiting for device response was timeout.(dev_id=%u, chan_id=%u, msg_type=%u)\n",
153	                dev_id, chan_id, msg_type);
154	            goto destroy_session;
155	        }
156	        (void)usleep(500); /* 500 */
157	        wait_count++;
158	        ret = sem_trywait(sem);
159	    }
160	
161	    if (msg_type == (uint32_t)PROF_HDC_CMD_GET_CHANNEL) {
162	        return DRV_ERROR_NONE;
163	    } else {
164	        return prof_comm_errcode_convert(prof_hdc_get_chan_info(dev_id, chan_id)->ret_val);
165	    }
166	
167	destroy_session:
168	    if (msg_type == (uint32_t)PROF_HDC_CMD_GET_CHANNEL) {
169	        prof_hdc_get_info(dev_id)->verify++;
170	    }
171	
172	    drv_ret = prof_session_destroy(dev_id, chan_id);
173	    if ((drv_ret != DRV_ERROR_NONE) && (drv_ret != (int)DRV_ERROR_NOT_SUPPORT)) {
174	        PROF_ERR("Failed to destroy hdc session client. (ret=%d)\n", (int)drv_ret);
175	    }
176	
177	    return DRV_ERROR_WAIT_TIMEOUT;
178	}
179	
180	STATIC drvError_t prof_hdc_get_channels_msg_send(uint32_t dev_id, struct prof_hdc_info *info)
181	{
182	    struct prof_hdc_msg *msg = NULL;
183	    uint32_t msg_len = sizeof(struct prof_hdc_msg) + sizeof(struct prof_channel_list);
184	    drvError_t ret;
185	
186	    msg = (struct prof_hdc_msg *)calloc(1, msg_len);
187	    if (msg == NULL) {
188	        PROF_ERR("Failed to alloc hdc_msg. (dev_id=%u, len=%u)\n", dev_id, msg_len);
189	        return DRV_ERROR_MALLOC_FAIL;
190	    }
191	
192	    msg->msg_type = (int)PROF_HDC_CMD_GET_CHANNEL;
193	    msg->cmd_verify = info->verify;
194	    msg->data_len = sizeof(struct prof_channel_list);
195	
196	    ret = prof_hdc_msg_send(dev_id, 0, (uint8_t *)msg, msg_len);
197	    if (ret != DRV_ERROR_NONE) {
198	        PROF_ERR("Failed to send message to device. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
199	    }
200	
201	    free(msg);
202	    return ret;
203	}
204	
205	STATIC drvError_t prof_hdc_start_msg_send(uint32_t dev_id, uint32_t chan_id, struct prof_user_start_para *para)
206	{
207	    struct prof_hdc_msg *msg = NULL;
208	    struct prof_hdc_start_para *start = NULL;
209	    uint32_t msg_len = sizeof(struct prof_hdc_msg) + sizeof(struct prof_hdc_start_para);
210	    int ret;
211	    drvError_t drv_ret;
212	
213	    msg = (struct prof_hdc_msg *)calloc(1, msg_len);
214	    if (msg == NULL) {
215	        PROF_ERR("Failed to alloc hdc_msg. (dev_id=%u, chan_id=%u, len=%u)\n", dev_id, chan_id, msg_len);
216	        return DRV_ERROR_MALLOC_FAIL;
217	    }
218	
219	    msg->msg_type = (int)PROF_HDC_CMD_START;
220	    msg->channel_id = chan_id;
221	    msg->data_len = sizeof(struct prof_hdc_start_para);
222	    start = (struct prof_hdc_start_para *)(msg->data);
223	    start->sample_period = ((para->remote_pid == 0) ? para->sample_period : 0);
224	    start->user_data_size = para->user_data_size;
225	    if ((para->user_data != NULL) && (para->user_data_size != 0)) {
226	        ret = memcpy_s(start->user_data, PROF_USER_DATA_LEN, para->user_data, para->user_data_size);
227	        if (ret != 0) {
228	            PROF_ERR("Failed to copy user_data. (dev_id=%u, chan_id=%u, ret=%d, data_size=%u)\n",
229	                dev_id, chan_id, ret, para->user_data_size);
230	            free(msg);
231	            return DRV_ERROR_MEMORY_OPT_FAIL;
232	        }
233	    }
234	
235	    drv_ret = prof_hdc_msg_send(dev_id, chan_id, (uint8_t *)msg, msg_len);
236	    if (drv_ret != DRV_ERROR_NONE) {
237	        PROF_ERR("Failed to send message to device. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)drv_ret);
238	    }
239	
240	    free(msg);
241	    return drv_ret;
242	}
243	
244	STATIC drvError_t prof_hdc_stop_msg_send(uint32_t dev_id, uint32_t chan_id)
245	{
246	    struct prof_hdc_msg *msg = NULL;
247	    uint32_t msg_len = sizeof(struct prof_hdc_msg) + sizeof(struct prof_kernel_dfx_info);
248	    drvError_t ret;
249	
250	    msg = (struct prof_hdc_msg *)calloc(1, msg_len);
251	    if (msg == NULL) {
252	        PROF_ERR("Failed to alloc hdc_msg. (dev_id=%u, chan_id=%u, len=%u)\n", dev_id, chan_id, msg_len);
253	        return DRV_ERROR_MALLOC_FAIL;
254	    }
255	
256	    msg->msg_type = (int)PROF_HDC_CMD_STOP;
257	    msg->channel_id = chan_id;
258	    msg->data_len = sizeof(struct prof_kernel_dfx_info);
259	
260	    ret = prof_hdc_msg_send(dev_id, chan_id, (uint8_t *)msg, msg_len);
261	    if (ret != DRV_ERROR_NONE) {
262	        PROF_ERR("Failed to send message to device. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
263	    }
264	
265	    free(msg);
266	    return ret;
267	}
268	
269	STATIC drvError_t prof_hdc_flush_msg_send(uint32_t dev_id, uint32_t chan_id)
270	{
271	    struct prof_hdc_msg *msg = NULL;
272	    uint32_t msg_len = sizeof(struct prof_hdc_msg) + sizeof(uint32_t);
273	    drvError_t ret;
274	
275	    msg = (struct prof_hdc_msg *)calloc(1, msg_len);
276	    if (msg == NULL) {
277	        PROF_ERR("Failed to alloc hdc_msg. (dev_id=%u, chan_id=%u, len=%u)\n", dev_id, chan_id, msg_len);
278	        return DRV_ERROR_MALLOC_FAIL;
279	    }
280	
281	    msg->msg_type = (int)PROF_HDC_DATA_FLUSH;
282	    msg->channel_id = chan_id;
283	    msg->data_len = sizeof(uint32_t);
284	
285	    ret = prof_hdc_msg_send(dev_id, chan_id, (uint8_t *)msg, msg_len);
286	    if (ret != DRV_ERROR_NONE) {
287	        PROF_ERR("Failed to send message to device. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
288	    }
289	
290	    free(msg);
291	    return ret;
292	}
293	
294	STATIC void prof_hdc_receive_channels(uint32_t dev_id, struct prof_hdc_msg *msg_head, uint32_t total_len)
295	{
296	    struct prof_hdc_info *info = prof_hdc_get_info(dev_id);
297	    uint32_t expect_len = sizeof(struct prof_hdc_msg) + sizeof(struct prof_channel_list);
298	    int ret;
299	
300	    if (total_len != expect_len) {
301	        PROF_ERR("Invalid para. (dev_id=%u, total_len=%u, expect_len=%u)\n", dev_id, total_len, expect_len);
302	        return;
303	    }
304	
305	    if (msg_head->ret_val != PROF_OK) {
306	        PROF_ERR("The returned value was not [PROF_OK]. (dev_id=%u, ret_val=%d)\n", dev_id, msg_head->ret_val);
307	        return;
308	    }
309	
310	    (void)pthread_mutex_lock(&info->mutex);
311	    if (msg_head->cmd_verify != info->verify || info->channels == NULL) {
312	        PROF_ERR("Recv dev respond too late. (dev_id=%u, msg_verify=%u, expect_verify=%u)\n",
313	            dev_id, msg_head->cmd_verify, info->verify);
314	        (void)pthread_mutex_unlock(&info->mutex);
315	        return;
316	    }
317	
318	    ret = memcpy_s(info->channels, sizeof(struct prof_channel_list), msg_head->data, sizeof(struct prof_channel_list));
319	    if (ret != 0) {
320	        PROF_ERR("Failed to copy channels. (dev_id=%u, ret=%d)\n", dev_id, ret);
321	        (void)pthread_mutex_unlock(&info->mutex);
322	        return;
323	    }
324	    (void)sem_post(&info->sem);
325	
326	    ret = prof_session_destroy(dev_id, 0);
327	    if ((ret != PROF_OK) && (ret != (int)DRV_ERROR_NOT_SUPPORT)) {
328	        PROF_ERR("Failed to destroy hdc session client. (dev_id=%u, ret=%d)\n", dev_id, ret);
329	        (void)pthread_mutex_unlock(&info->mutex);
330	        return;
331	    }
332	
333	    (void)pthread_mutex_unlock(&info->mutex);
334	}
335	
336	STATIC void prof_hdc_receive_chan_respond(uint32_t dev_id, struct prof_hdc_msg *msg_head)
337	{
338	    struct prof_hdc_chan_info *chan_info = NULL;
339	    uint32_t chan_id = msg_head->channel_id;
340	    drvError_t ret;
341	
342	    if (chan_id >= PROF_CHANNEL_NUM_MAX) {
343	        PROF_ERR("Invalid para. (chan_id=%u)\n", chan_id);
344	        return;
345	    }
346	
347	    PROF_INFO("Received chan response. (msg_type=%d, dev_id=%u, chan_id=%u, ret_val=%d)\n",
348	        msg_head->msg_type, dev_id, chan_id, msg_head->ret_val);
349	
350	    chan_info = prof_hdc_get_chan_info(dev_id, chan_id);
351	    if (chan_info == NULL) {
352	        PROF_ERR("Failed to get chan_info. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
353	        return;
354	    }
355	
356	    chan_info->ret_val = msg_head->ret_val;
357	
358	    if ((msg_head->msg_type == (int)PROF_HDC_CMD_STOP) && (msg_head->ret_val == DRV_ERROR_NONE)) {
359	        ret = prof_session_destroy(dev_id, chan_id);
360	        if ((ret != DRV_ERROR_NONE) && (ret != DRV_ERROR_NOT_SUPPORT)) {
361	            PROF_ERR("Failed to destroy hdc session client. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, ret);
362	            return;
363	        }
364	    }
365	
366	    (void)sem_post(&chan_info->sem);
367	}
368	
369	STATIC void prof_hdc_receive_chan_data(uint32_t dev_id, struct prof_hdc_msg *msg_head, uint32_t total_len)
370	{
371	    struct prof_comm_core_notifier *notifier = prof_comm_get_notifier();
372	
373	    if (total_len != (sizeof(struct prof_hdc_msg) + msg_head->data_len)) {
374	        PROF_ERR("Invalid para. (dev_id=%u, total_len=%u, head_size=%lu, data_len=%u)\n",
375	            dev_id, total_len, sizeof(struct prof_hdc_msg), msg_head->data_len);
376	        return;
377	    }
378	
379	    if (msg_head->channel_id >= PROF_CHANNEL_NUM_MAX) {
380	        PROF_ERR("Invalid para. (dev_id=%u, chan_id=%u)\n", dev_id, msg_head->channel_id);
381	        return;
382	    }
383	
384	    if (msg_head->data_len > 0) {
385	        notifier->chan_report(dev_id, msg_head->channel_id, msg_head->data, msg_head->data_len, false);
386	    }
387	}
388	
389	void prof_hdc_msg_proc(uint32_t dev_id, void *msg, uint32_t len)
390	{
391	    struct prof_hdc_msg *msg_head = NULL;
392	
393	    if ((dev_id >= (uint32_t)DEV_NUM) || (msg == NULL) || (len < sizeof(struct prof_hdc_msg))) {
394	        PROF_ERR("Invalid para. (dev_id=%u, msg_len=%u, min_len=%lu)\n", dev_id, len, sizeof(struct prof_hdc_msg));
395	        return;
396	    }
397	
398	    msg_head = (struct prof_hdc_msg *)msg;
399	    PROF_DEBUG("Recv dev respond. (dev_id=%u, msg_type=%d)\n", dev_id, msg_head->msg_type);
400	    switch (msg_head->msg_type) {
401	        case PROF_HDC_CMD_GET_CHANNEL:
402	            prof_hdc_receive_channels(dev_id, msg_head, len);
403	            break;
404	        case PROF_HDC_CMD_START:
405	        case PROF_HDC_CMD_STOP:
406	        case PROF_HDC_DATA_FLUSH:
407	            prof_hdc_receive_chan_respond(dev_id, msg_head);
408	            break;
409	        case PROF_HDC_DATA:
410	            prof_hdc_receive_chan_data(dev_id, msg_head, len);
411	            break;
412	        default:
413	            PROF_ERR("Profile detected an unknown msg. (dev_id=%u, msg_type=%d)\n", dev_id, msg_head->msg_type);
414	            return;
415	    }
416	}
417	
418	STATIC drvError_t prof_hdc_try_lock(struct prof_hdc_info *info)
419	{
420	    int wait_count = 0;
421	    drvError_t ret = DRV_ERROR_WAIT_TIMEOUT;
422	
423	    while (wait_count < PROF_HDC_TRY_COUNT) {
424	        if (CAS(&info->status, PROF_HDC_GET_CHANNELS_IDLE, PROF_HDC_GET_CHANNELS_OCCUPY)) {
425	            ret = DRV_ERROR_NONE;
426	            break;
427	        }
428	        wait_count++;
429	        (void)usleep(PROF_HDC_TRY_WAIT_TIME);
430	    }
431	
432	    return ret;
433	}
434	
435	STATIC void prof_hdc_unlock(struct prof_hdc_info *info)
436	{
437	    ATOMIC_SET(&info->status, PROF_HDC_GET_CHANNELS_IDLE);
438	}
439	
440	drvError_t prof_hdc_get_channels(uint32_t dev_id, struct prof_channel_list *channels)
441	{
442	    struct prof_hdc_info *info = prof_hdc_get_info(dev_id);
443	    drvError_t ret;
444	
445	    ret = prof_hdc_try_lock(info);
446	    if (ret != DRV_ERROR_NONE) {
447	        PROF_ERR("Failed to get permission. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
448	        return ret;
449	    }
450	
451	    (void)pthread_mutex_lock(&info->mutex);
452	    (void)sem_init(&info->sem, 0, 0);
453	    info->channels = channels;
454	    (void)pthread_mutex_unlock(&info->mutex);
455	
456	    ret = prof_hdc_get_channels_msg_send(dev_id, info);
457	    if (ret != DRV_ERROR_NONE) {
458	        goto exit; 
459	    }
460	
461	    ret = prof_hdc_get_ret(dev_id, 0, PROF_HDC_RESPOND_MAXTIME + PROF_HDC_SESSION_CLOSE_MAXTIME, PROF_HDC_CMD_GET_CHANNEL);
462	    if (ret != DRV_ERROR_NONE) {
463	        PROF_ERR("Failed to get channels. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
464	    }
465	
466	exit:
467	    (void)pthread_mutex_lock(&info->mutex);
468	    info->channels = NULL;
469	    (void)pthread_mutex_unlock(&info->mutex);
470	    prof_hdc_unlock(info);
471	
472	    return ret;
473	}
474	
475	drvError_t prof_hdc_start(uint32_t dev_id, uint32_t chan_id, struct prof_user_start_para *para)
476	{
477	    struct process_sign sign_info = {0};
478	    drvError_t ret;
479	
480	    ret = drvGetProcessSign(&sign_info);
481	    if (ret != DRV_ERROR_NONE) {
482	        PROF_ERR("Failed get process sign. (devid=%u, chan_id=%u, ret=%d).\n", dev_id, chan_id, (int)ret);
483	        return ret;
484	    }
485	
486	    ret = prof_hdc_chan_sem_init(dev_id, chan_id);
487	    if (ret != DRV_ERROR_NONE) {
488	        return ret;
489	    }
490	
491	    ret = prof_hdc_start_msg_send(dev_id, chan_id, para);
492	    if (ret != DRV_ERROR_NONE) {
493	        return ret;
494	    }
495	
496	    return prof_hdc_get_ret(dev_id, chan_id, PROF_HDC_RESPOND_MAXTIME, PROF_HDC_CMD_START);
497	}
498	
499	drvError_t prof_hdc_stop(uint32_t dev_id, uint32_t chan_id)
500	{
501	    drvError_t ret;
502	
503	    ret = prof_hdc_chan_sem_init(dev_id, chan_id);
504	    if (ret != DRV_ERROR_NONE) {
505	        return ret;
506	    }
507	
508	    ret = prof_hdc_stop_msg_send(dev_id, chan_id);
509	    if (ret != DRV_ERROR_NONE) {
510	        return ret;
511	    }
512	
513	    return prof_hdc_get_ret(dev_id, chan_id, PROF_HDC_RESPOND_MAXTIME + PROF_HDC_SESSION_CLOSE_MAXTIME, PROF_HDC_CMD_STOP);
514	}
515	
516	drvError_t prof_hdc_flush(uint32_t dev_id, uint32_t chan_id)
517	{
518	    drvError_t ret;
519	
520	    ret = prof_hdc_chan_sem_init(dev_id, chan_id);
521	    if (ret != DRV_ERROR_NONE) {
522	        return ret;
523	    }
524	
525	    ret = prof_hdc_flush_msg_send(dev_id, chan_id);
526	    if (ret != DRV_ERROR_NONE) {
527	        return ret;
528	    }
529	
530	    return prof_hdc_get_ret(dev_id, chan_id, PROF_HDC_FLUSH_MAXTIME, PROF_HDC_DATA_FLUSH);
531	}
532	
533	STATIC void __attribute__((constructor)) prof_hdc_proc_init(void)
534	{
535	    prof_hdc_register_msg_proc_func(prof_hdc_msg_proc);
536	    PROF_INFO("Register prof hdc msg proc successfully.\n");
537	}
538	
539	#else
540	int prof_hdc_ut_test(void)
541	{
542	    return 0;
543	}
544	#endif
