86	            PROF_ERR("Failed to send stop event. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
87	            /* send failed maybe cp or adda proc had exited, continue stop kernel chan */
88	        }
89	    }
90	
91	    ret = prof_hdc_stop(dev_id, chan_id);
92	
93	    prof_buff_wait_read_empty(buff, dev_id, chan_id);
94	
95	    return ret;
96	}
