41	STATIC void prof_hdc_session_close(struct drvHdcEvent event)
42	{
43	    drvError_t ret;
44	    int i, j;
45	
46	    (void)pthread_mutex_lock(&(g_prof_hdc_info.prof_hdc_mutex));
47	
48	    ret = (int)drvHdcEpollCtl(g_prof_hdc_info.epoll, HDC_EPOLL_CTL_DEL, (void *)event.data, &event);
49	    PROF_RUN_INFO("Profile HDC poll deleted the session. (ret=%d)\r\n", ret);
50	
51	    for (i = 0; i < DEV_NUM; i++) {
52	        if (g_prof_hdc_info.session[i] == (HDC_SESSION)event.data) {
53	            g_prof_hdc_info.session_count--;
54	            for (j = 0; j < PROF_CHANNEL_NUM_MAX; j++) {
55	                g_prof_hdc_info.prof_channel_enable_flag[i][j] = 0;
56	            }
57	            break;
58	        }
59	    }
60	
61	    (void)pthread_mutex_unlock(&(g_prof_hdc_info.prof_hdc_mutex));
62	}
63	
64	STATIC void prof_wait_epoll_client_recv_thread_exit(void)
65	{
66	    int cnt = 0;
67	    long timecost;
68	    struct timespec start = {0};
69	    struct timespec end = {0};
70	    /* wait recv thread exit */
71	    (void)clock_gettime(CLOCK_MONOTONIC, &start);
72	    while ((g_prof_hdc_info.recv_thread_run_flag != PROF_HDC_RECEIVE_THREAD_STOP) &&
73	        (cnt < 5000)) { /* wait times max 5000 */
74	        (void)usleep(1000), /* 1000 us */
75	        cnt++;
76	    }
77	    (void)clock_gettime(CLOCK_MONOTONIC, &end);
78	    /* 1000: ms */
79	    timecost = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / PROF_NSEC_PER_MSECOND;
80	    /* > 10 ms print warn */
81	    if (timecost > 10) {
82	        PROF_WARN("Profiled waited for the ending of thread at the poll. (timecost=%ld)\n", timecost);
83	    }
84	    if (g_prof_hdc_info.recv_thread_run_flag == PROF_HDC_RECEIVE_THREAD_RUNNING) {
85	        PROF_WARN("Profile waited for the ending of thread at the poll. The thread was not over. (cnt=%d)\n", cnt);
86	    }
87	}
88	
89	STATIC void prof_handle_hdc_events(struct drvHdcEvent *events, int eventnum)
90	{
91	    struct drvHdcMsg *hdc_msg = NULL;
92	    HDC_SESSION recv_session;
93	    struct drvHdcEvent event;
94	    char *p_buf = NULL;
95	    int dev_id = 0;
96	    int recv_buf_count;
97	    int buf_len = 0;
98	    drvError_t ret;
99	    int i;
100	
101	    for (i = 0; i < eventnum; i++) {
102	        recv_session = (HDC_SESSION)events[i].data;
103	
104	        if ((events[i].events & HDC_EPOLL_SESSION_CLOSE) != 0) {
105	            event.events = HDC_EPOLL_DATA_IN;
106	            event.data = (uintptr_t)recv_session;
107	            prof_hdc_session_close(event);
108	            continue;
109	        }
110	
111	        ret = drvHdcAllocMsg(recv_session, &hdc_msg, 1);
112	        if (ret != DRV_ERROR_NONE) {
113	            PROF_ERR("Failed to invoke function [drvHdcAllocMsg]. (ret=%d)\n", (int)ret);
114	            continue;
115	        }
116	
117	        ret = halHdcRecv(recv_session, hdc_msg, 0, 1, &recv_buf_count, 0);
118	        if (ret != DRV_ERROR_NONE) {
119	            if (ret == DRV_ERROR_NON_BLOCK) {
120	                PROF_DEBUG("No report.\n");
121	            } else {
122	                PROF_ERR("Failed to invoke function [halHdcRecv]. (ret=%d)\n", (int)ret);
123	            }
124	            goto hdc_msg_free;
125	        }
126	
127	        ret = drvHdcGetMsgBuffer(hdc_msg, 0, &p_buf, &buf_len);
128	        if (ret != DRV_ERROR_NONE) {
129	            PROF_ERR("Failed to invoke function [drvHdcGetMsgBuffer]. (ret=%d)\n", (int)ret);
130	            goto hdc_msg_free;
131	        }
132	        ret = halHdcGetSessionAttr(recv_session, HDC_SESSION_ATTR_DEV_ID, &dev_id);
133	        if (ret != DRV_ERROR_NONE) {
134	            PROF_ERR("Failed to invoke function [halHdcGetSessionAttr] to get the device ID. (ret=%d)\n", (int)ret);
135	            goto hdc_msg_free;
136	        }
137	
138	        prof_hdc_call_msg_proc_func((uint32_t)dev_id, (unsigned char *)p_buf, (uint32_t)buf_len);
139	
140	hdc_msg_free:
141	        ret = drvHdcFreeMsg(hdc_msg);
142	        if (ret != DRV_ERROR_NONE) {
143	            PROF_ERR("Failed to invoke function [drvHdcFreeMsg]. (ret=%d)\n", (int)ret);
144	        }
145	    }
146	}
147	
148	STATIC void prof_recv_all_session_msg(void)
149	{
150	    struct drvHdcEvent events = {0};
151	    int i;
152	
153	    for (i = 0; i < DEV_NUM; i++) {
154	        if (g_prof_hdc_info.prof_channel_num_count[i] > 0) {
155	            PROF_DEBUG("try recv per session report. (devid=%d)\n", i);
156	            events.data = (uintptr_t)g_prof_hdc_info.session[i];
157	            prof_handle_hdc_events(&events, 1);
158	        }
159	    }
160	}
161	
162	STATIC drvError_t prof_client_create(void)
163	{
164	    drvError_t ret;
165	
166	    ret = drvHdcEpollCreate(PROF_HDC_EVENT_NUM_MAX, &g_prof_hdc_info.epoll);
167	    if (ret != DRV_ERROR_NONE) {
168	        PROF_ERR("Failed to invoke drvHdcEpollCreate. (ret=%d)\n", (int)ret);
169	        return ret;
170	    }
171	
172	    ret = drvHdcClientCreate(&g_prof_hdc_info.client, PROF_HDC_EVENT_NUM_MAX, HDC_SERVICE_TYPE_PROF, 0);
173	    if (ret != DRV_ERROR_NONE) {
174	        PROF_ERR("Failed to invoke drvHdcClientCreate. (ret=%d)\n", (int)ret);
175	        goto prof_client_create_err;
176	    }
177	
178	    return ret;
179	
180	prof_client_create_err:
181	    ret = drvHdcEpollClose(g_prof_hdc_info.epoll);
182	    if (ret != DRV_ERROR_NONE) {
183	        PROF_ERR("Failed to close the poll of HDC driver. (ret=%d)\n", (int)ret);
184	    }
185	    return ret;
186	}
187	
188	STATIC void prof_client_destroy(void)
189	{
190	    drvError_t ret;
191	
192	    ret = drvHdcEpollClose(g_prof_hdc_info.epoll);
193	    if (ret != DRV_ERROR_NONE) {
194	        PROF_ERR("Failed to close the poll of HDC driver. (ret=%d)\n", (int)ret);
195	    }
196	
197	    ret = drvHdcClientDestroy(g_prof_hdc_info.client);
198	    if (ret != DRV_ERROR_NONE) {
199	        PROF_ERR("Failed to destroy HDC client. (ret=%d)\n", (int)ret);
200	    }
201	
202	    /* debug log , need to be del before merge*/
203	    PROF_INFO("HDC client destroyed.\n");
204	}
205	
206	#define PROF_EPOLL_SLEEP_TIME 100000
207	STATIC struct drvHdcEvent g_prof_epoll_events[PROF_HDC_EVENT_NUM_MAX];
208	STATIC void *prof_epoll_client_recv(void *arg)
209	{
210	    HDC_EPOLL epoll = (HDC_EPOLL)arg;
211	    int eventnum;
212	    drvError_t ret;
213	    bool wait_epoll_thread_end = false;
214	
215	    g_prof_hdc_info.recv_thread_run_flag = PROF_HDC_RECEIVE_THREAD_RUNNING;
216	    while (g_prof_hdc_info.prof_epoll_client_recv_flag == PROF_HDC_RECEIVE_THREAD_ENABLE) {
217	        if (wait_epoll_thread_end) {
218	            // if drvHdcEpollWait returned fail, should wait epoll thread end, and then release hdc epoll and client memory
219	            (void)usleep(PROF_EPOLL_SLEEP_TIME); // 100ms
220	            continue;
221	        }
222	
223	        eventnum = PROF_HDC_EVENT_NUM_MAX;
224	        ret = drvHdcEpollWait(epoll, &g_prof_epoll_events[0], PROF_HDC_EVENT_NUM_MAX, 1000, &eventnum); /* timeout 1000ms */
225	        if ((ret != DRV_ERROR_NONE) || (eventnum < 0) || ((uint32_t)eventnum > PROF_HDC_EVENT_NUM_MAX)) {
226	            if (ret == DRV_ERROR_EPOLL_CLOSE) {
227	                PROF_INFO("Profile HDC was closed. The client receiving thread at the poll was over."
228	                    " (ret=%d)\n", ret);
229	            } else {
230	                PROF_ERR("Failed to invoke function [drvHdcEpollWait] or the variable [eventnum] was invalid."
231	                    " (ret=%d, eventnum=%d)\n", ret, eventnum);
232	            }
233	            wait_epoll_thread_end = true;
234	            continue;
235	        }
236	
237	        if (eventnum == 0) {
238	            PROF_DEBUG("Wait report timeout, try recv all session msg.\n");
239	            prof_recv_all_session_msg();
240	            continue;
241	        }
242	
243	        prof_handle_hdc_events(&g_prof_epoll_events[0], eventnum);
244	    }
245	
246	    prof_client_destroy();
247	
248	    g_prof_hdc_info.recv_thread_run_flag = PROF_HDC_RECEIVE_THREAD_STOP;
249	
250	    PROF_INFO("Epoll recv thread exit.\n");
251	    return NULL;
252	}
253	
254	STATIC drvError_t prof_create_receive_thread(void)
255	{
256	    pthread_attr_t attr;
257	    drvError_t ret;
258	
259	    (void)pthread_attr_init(&attr);
260	    (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
261	    (void)pthread_attr_setscope(&attr, PTHREAD_SCOPE_SYSTEM);
262	    ret = pthread_create(&g_prof_hdc_info.epoll_thread, &attr, prof_epoll_client_recv, (void *)g_prof_hdc_info.epoll);
263	    if (ret != DRV_ERROR_NONE) {
264	        PROF_ERR("Failed to create the thread. (ret=%d)\n", ret);
265	    }
266	    (void)pthread_attr_destroy(&attr);
267	
268	    return ret;
269	}
270	
271	STATIC void prof_destroy_receive_thread(void)
272	{
273	    g_prof_hdc_info.prof_epoll_client_recv_flag = PROF_HDC_RECEIVE_THREAD_DISABLE;
274	}
275	
276	STATIC drvError_t prof_client_and_receive_thread_create(void)
277	{
278	    drvError_t ret;
279	
280	    if (g_prof_hdc_info.prof_epoll_client_recv_flag == PROF_HDC_RECEIVE_THREAD_ENABLE) {
281	        return DRV_ERROR_NONE;
282	    }
283	
284	    if (g_prof_hdc_info.recv_thread_run_flag == PROF_HDC_RECEIVE_THREAD_RUNNING) {
285	        prof_wait_epoll_client_recv_thread_exit();
286	    }
287	
288	    ret = prof_client_create();
289	    if (ret != DRV_ERROR_NONE) {
290	        PROF_ERR("Failed to create profile client. (ret=%d)\n", (int)ret);
291	        return ret;
292	    }
293	
294	    g_prof_hdc_info.session_count = 0;
295	    g_prof_hdc_info.prof_epoll_client_recv_flag = PROF_HDC_RECEIVE_THREAD_ENABLE;
296	
297	    ret = prof_create_receive_thread();
298	    if (ret != DRV_ERROR_NONE) {
299	        PROF_ERR("Failed to create receive thread. (ret=%d)\n", (int)ret);
300	        g_prof_hdc_info.prof_epoll_client_recv_flag = PROF_HDC_RECEIVE_THREAD_DISABLE;
301	        prof_client_destroy();
302	        return ret;
303	    }
304	
305	    return DRV_ERROR_NONE;
306	}
307	
308	STATIC drvError_t prof_per_session_connect(uint32_t dev_id, uint32_t chan_id)
309	{
310	    struct drvHdcEvent event;
311	    drvError_t ret;
312	
313	    if (g_prof_hdc_info.prof_channel_enable_flag[dev_id][chan_id] == 1) {
314	        return DRV_ERROR_NONE;
315	    }
316	
317	    if (g_prof_hdc_info.prof_channel_num_count[dev_id] != 0) {
318	        g_prof_hdc_info.prof_channel_num_count[dev_id]++;
319	        g_prof_hdc_info.prof_channel_enable_flag[dev_id][chan_id] = 1;
320	        return DRV_ERROR_NONE;
321	    }
322	
323	    ret = drvHdcSessionConnect(0, (int)dev_id, g_prof_hdc_info.client, &g_prof_hdc_info.session[dev_id]);
324	    if (ret != DRV_ERROR_NONE) {
325	        PROF_ERR("Failed to invoke function [drvHdcSessionConnect]. (ret=%d)\n", (int)ret);
326	        return ret;
327	    }
328	
329	    PROF_INFO("The function [drvHdcSessionConnect] invoked was success. (dev_id=%u)\n", dev_id);
330	
331	    ret = drvHdcSetSessionReference(g_prof_hdc_info.session[dev_id]);
332	    if (ret != DRV_ERROR_NONE) {
333	        PROF_ERR("Failed to invoke function [drvHdcSetSessionReference] to add the session. (ret=%d)\n", (int)ret);
334	        (void)drvHdcSessionClose(g_prof_hdc_info.session[dev_id]);
335	        return ret;
336	    }
337	
338	    event.events = HDC_EPOLL_DATA_IN;
339	    event.data = (uintptr_t)g_prof_hdc_info.session[dev_id];
340	    ret = drvHdcEpollCtl(g_prof_hdc_info.epoll, HDC_EPOLL_CTL_ADD, (void *)g_prof_hdc_info.session[dev_id], &event);
341	    if (ret != DRV_ERROR_NONE) {
342	        PROF_ERR("Failed to add the session. (ret=%d)\n", (int)ret);
343	        (void)drvHdcSessionClose(g_prof_hdc_info.session[dev_id]);
344	        return ret;
345	    }
346	
347	    g_prof_hdc_info.session_count++;
348	    g_prof_hdc_info.prof_channel_num_count[dev_id]++;
349	    g_prof_hdc_info.prof_channel_enable_flag[dev_id][chan_id] = 1;
350	
351	    return DRV_ERROR_NONE;
352	}
353	
354	STATIC drvError_t prof_session_connect(uint32_t dev_id, uint32_t chan_id)
355	{
356	    drvError_t ret;
357	
358	    ret = prof_client_and_receive_thread_create();
359	    if (ret != DRV_ERROR_NONE) {
360	        PROF_ERR("Failed to create the thread for client to connect with profile sessions. (ret=%d)\n", ret);
361	        return ret;
362	    }
363	
364	    ret = prof_per_session_connect(dev_id, chan_id);
365	    if (ret != DRV_ERROR_NONE) {
366	        prof_destroy_receive_thread();
367	        return ret;
368	    }
369	
370	    return DRV_ERROR_NONE;
371	}
372	
373	STATIC drvError_t prof_session_msg_send(HDC_SESSION session, unsigned char *buff_base, uint32_t buff_len)
374	{
375	    struct prof_hdc_msg *cmd_msg = (struct prof_hdc_msg *)buff_base;
376	    struct drvHdcMsg *hdc_msg = NULL;
377	    drvError_t ret;
378	
379	    ret = drvHdcAllocMsg(session, &hdc_msg, 1);
380	    if (ret != DRV_ERROR_NONE) {
381	        PROF_ERR("Failed to invoke function [drvHdcAllocMsg]. (ret=%d)\n", (int)ret);
382	        return ret;
383	    }
384	
385	    ret = drvHdcAddMsgBuffer(hdc_msg, (char *)buff_base, (int)buff_len);
386	    if (ret != DRV_ERROR_NONE) {
387	        PROF_ERR("Failed to invoke function [drvHdcAddMsgBuffer]. (ret=%d)\n", (int)ret);
388	        (void)drvHdcFreeMsg(hdc_msg);
389	        return ret;
390	    }
391	
392	    (void)pthread_mutex_unlock(&(g_prof_hdc_info.prof_hdc_mutex));
393	
394	    ret = halHdcSend(session, hdc_msg, 0, 0);
395	    if (ret != DRV_ERROR_NONE) {
396	        PROF_ERR("Failed to invoke function [halHdcSend]. (ret=%d)\n", (int)ret);
397	        (void)drvHdcFreeMsg(hdc_msg);
398	        (void)pthread_mutex_lock(&(g_prof_hdc_info.prof_hdc_mutex));
399	        return ret;
400	    }
401	
402	    PROF_DEBUG("Profile command sending was success. (msg_type=%d)\n", cmd_msg->msg_type);
403	
404	    ret = drvHdcFreeMsg(hdc_msg);
405	    if (ret != DRV_ERROR_NONE) {
406	        PROF_ERR("Failed to invoke function [drvHdcFreeMsg]. (ret=%d)\n", (int)ret);
407	    }
408	
409	    (void)pthread_mutex_lock(&(g_prof_hdc_info.prof_hdc_mutex));
410	    return ret;
411	}
412	
413	STATIC drvError_t prof_per_session_disconnect(uint32_t dev_id, uint32_t chan_id)
414	{
415	    struct prof_hdc_msg cmd_msg;
416	    struct drvHdcEvent event;
417	    drvError_t ret;
418	    HDC_SESSION session_tmp = NULL;
419	    event.events = HDC_EPOLL_DATA_IN;
420	
421	    if (g_prof_hdc_info.prof_channel_num_count[dev_id] == 0 ||
422	        g_prof_hdc_info.prof_channel_enable_flag[dev_id][chan_id] == 0) {
423	        PROF_RUN_INFO("Profile session had no channel client. HDC session had been closed. (dev_id=%u)\n",
424	                      dev_id);
425	        return DRV_ERROR_NOT_SUPPORT;
426	    }
427	
428	    g_prof_hdc_info.prof_channel_num_count[dev_id]--;
429	    g_prof_hdc_info.prof_channel_enable_flag[dev_id][chan_id] = 0;
430	    if (g_prof_hdc_info.prof_channel_num_count[dev_id] != 0) {
431	        return DRV_ERROR_NONE;
432	    }
433	
434	    session_tmp = g_prof_hdc_info.session[dev_id];
435	    ret = drvHdcEpollCtl(g_prof_hdc_info.epoll, HDC_EPOLL_CTL_DEL, (void *)session_tmp, &event);
436	    if (ret != DRV_ERROR_NONE) {
437	        PROF_ERR("Failed to  delete the session. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
438	        return ret;
439	    }
440	
441	    /* notice device close session */
442	    cmd_msg.msg_type = PROF_HDC_CLOSE_SESSION;
443	    ret = prof_session_msg_send(session_tmp, (unsigned char *)&cmd_msg, sizeof(struct prof_hdc_msg));
444	    if (ret != DRV_ERROR_NONE) {
445	        PROF_WARN("Unsuccessful to make profile session send messages. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
446	    }
447	
448	    ret = drvHdcSessionClose(session_tmp);
449	    if (ret != DRV_ERROR_NONE) {
450	        PROF_ERR("Failed to close session for profile device ID. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
451	        return ret;
452	    }
453	
454	    g_prof_hdc_info.session_count--;
455	    PROF_INFO("Profile HDC Session had closed successfully. (dev_id=%u)\n", dev_id);
456	
457	    return DRV_ERROR_NONE;
458	}
459	
460	drvError_t prof_session_destroy(uint32_t dev_id, uint32_t chan_id)
461	{
462	    drvError_t ret;
463	
464	    (void)pthread_mutex_lock(&(g_prof_hdc_info.prof_hdc_mutex));
465	
466	    ret = prof_per_session_disconnect(dev_id, chan_id);
467	    if (ret != DRV_ERROR_NONE) {
468	        (void)pthread_mutex_unlock(&(g_prof_hdc_info.prof_hdc_mutex));
469	        return ret;
470	    }
471	
472	    if (g_prof_hdc_info.session_count == 0) {
473	        prof_destroy_receive_thread();
474	    }
475	
476	    (void)pthread_mutex_unlock(&(g_prof_hdc_info.prof_hdc_mutex));
477	
478	    return DRV_ERROR_NONE;
479	}
480	
481	drvError_t prof_hdc_msg_send(uint32_t dev_id, uint32_t chan_id, unsigned char *buff_base, uint32_t buff_len)
482	{
483	    drvError_t ret;
484	
485	    (void)pthread_mutex_lock(&(g_prof_hdc_info.prof_hdc_mutex));
486	    ret = prof_session_connect(dev_id, chan_id);
487	    if (ret != DRV_ERROR_NONE) {
488	        (void)pthread_mutex_unlock(&(g_prof_hdc_info.prof_hdc_mutex));
489	        PROF_ERR("Failed to connect the prof session. (ret=%d, dev_id=%u, chan_id=%u)\n", (int)ret, dev_id, chan_id);
490	        return ret;
491	    }
492	
493	    ret = prof_session_msg_send(g_prof_hdc_info.session[dev_id], buff_base, buff_len);
494	    if (ret != DRV_ERROR_NONE) {
495	        (void)pthread_mutex_unlock(&(g_prof_hdc_info.prof_hdc_mutex));
496	        (void)prof_session_destroy(dev_id, chan_id);
497	        return ret;
498	    }
499	
500	    (void)pthread_mutex_unlock(&(g_prof_hdc_info.prof_hdc_mutex));
501	
502	    return DRV_ERROR_NONE;
503	}
504	#else
505	int prof_hdc_comm_ut_test(void)
506	{
507	    return 0;
508	}
509	#endif
