27	static drvError_t prof_urma_chan_init(uint32_t dev_id, uint32_t chan_id, bool event_flag, char **priv)
28	{
29	    struct prof_urma_chan_priv *chan_priv = NULL;
30	    drvError_t ret;
31	
32	    (void)event_flag;
33	
34	    chan_priv = (struct prof_urma_chan_priv *)malloc(sizeof(struct prof_urma_chan_priv));
35	    if (chan_priv == NULL) {
36	        PROF_ERR("Failed to alloc chan_priv. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
37	        return DRV_ERROR_MALLOC_FAIL;
38	    }
39	
40	    chan_priv->urma_chan_info = prof_urma_chan_info_creat(dev_id, chan_id);
41	    if (chan_priv->urma_chan_info == NULL) {
42	        free(chan_priv);
43	        PROF_ERR("Failed to create urma_info. (dev_id=%u, dev_id=%u)\n", dev_id, chan_id);
44	        return DRV_ERROR_PARA_ERROR;
45	    }
46	
47	    ret = prof_buff_init(chan_id, &chan_priv->buff);
48	    if (ret != DRV_ERROR_NONE) {
49	        prof_urma_chan_info_destroy(chan_priv->urma_chan_info);
50	        free(chan_priv);
51	        PROF_ERR("Failed to init buff. (dev_id=%u, dev_id=%u)\n", dev_id, chan_id);
52	        return ret;
53	    }
54	
55	    *priv = (char *)chan_priv;
56	    return DRV_ERROR_NONE;
57	}
58	
59	static void prof_urma_chan_uninit(char **priv)
60	{
61	    struct prof_urma_chan_priv *chan_priv = (struct prof_urma_chan_priv *)(*priv);
62	
63	    prof_buff_uninit(&chan_priv->buff);
64	    prof_urma_chan_info_destroy(chan_priv->urma_chan_info);
65	    free(chan_priv);
66	    *priv = NULL;
67	}
