69	static drvError_t prof_urma_chan_start(uint32_t dev_id, uint32_t chan_id, struct prof_user_start_para *para, char *priv)
70	{
71	    struct  prof_urma_chan_priv *chan_priv = (struct prof_urma_chan_priv *)priv;
72	    struct  prof_urma_start_para urma_start_para = {0};
73	    struct prof_user_stop_para stop_para = {0};
74	    drvError_t ret;
75	
76	    urma_start_para.data_buff_addr = (uint64_t)(uintptr_t)prof_buff_get_buf_addr(chan_priv->buff);
77	    urma_start_para.data_buff_len = prof_buff_get_buf_size(chan_priv->buff);
78	    urma_start_para.rptr_addr = (uint64_t)(uintptr_t)prof_buff_get_readptr_addr(chan_priv->buff);
79	    urma_start_para.rptr_size = prof_buff_get_readptr_size(chan_priv->buff);
80	
81	    ret = prof_urma_start(dev_id, chan_id, para, &urma_start_para, chan_priv->urma_chan_info);
82	    if (ret != DRV_ERROR_NONE) {
83	        PROF_ERR("Failed to start prof by urma. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
84	        return ret;
85	    }
86	
87	    if (para->remote_pid != 0) {
88	        ret = prof_event_start(dev_id, chan_id, para);
89	        if (ret != DRV_ERROR_NONE) {
90	            stop_para.remote_pid = para->remote_pid;
91	            (void)prof_urma_stop(dev_id, chan_id, &stop_para, chan_priv->urma_chan_info);
92	            PROF_ERR("Failed to send start event. (devid=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
93	            return ret;
94	        }
95	    }
96	
97	    return DRV_ERROR_NONE;
98	}
99	
100	static drvError_t prof_urma_chan_stop(uint32_t dev_id, uint32_t chan_id, struct prof_user_stop_para *para, char *priv)
101	{
102	    struct  prof_urma_chan_priv *chan_priv = (struct prof_urma_chan_priv *)priv;
103	    drvError_t ret;
104	
105	    if (para->remote_pid != 0) {
106	        ret = prof_event_stop(dev_id, chan_id, para);
107	        if (ret != DRV_ERROR_NONE) {
108	            PROF_ERR("Failed to send stop event. (devid=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
109	            return ret;
110	        }
111	    }
112	
113	    ret = prof_urma_stop(dev_id, chan_id, para, chan_priv->urma_chan_info);
114	
115	    prof_buff_wait_read_empty(chan_priv->buff, dev_id, chan_id);
116	
117	    return DRV_ERROR_NONE;
118	}
119	
120	static drvError_t prof_urma_chan_flush(uint32_t dev_id, uint32_t chan_id, uint32_t *data_len, char *priv)
121	{
122	    struct  prof_urma_chan_priv *chan_priv = (struct prof_urma_chan_priv *)priv;
123	    drvError_t ret;
124	
125	    ret = prof_urma_flush(dev_id, chan_id);
126	    if (ret != DRV_ERROR_NONE) {
127	        return ret;
128	    }
129	
130	    *data_len = prof_buff_get_data_len(chan_priv->buff);
131	    return DRV_ERROR_NONE;
132	}
133	
134	static int prof_urma_chan_read(uint32_t dev_id, uint32_t chan_id, prof_user_read_para_t *read_para, char *priv)
135	{
136	    struct  prof_urma_chan_priv *chan_priv = (struct prof_urma_chan_priv *)priv;
137	    drvError_t ret;
138	    int read_len;
139	
140	    read_len = prof_buff_read(chan_priv->buff, read_para->out_buf, read_para->buf_size);
141	    if (read_len <= 0) {
142	        return read_len;
143	    }
144	
145	    if (read_para->write_rptr_flag == false) {
146	        /* the addr of remote rptr may be null when channel is stopping or starting */
147	        PROF_WARN("The channel is not ready yet, don't write remote rptr. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
148	        return read_len;
149	    }
150	
151	    ret = prof_urma_write_remote_r_ptr(dev_id, chan_id, chan_priv->urma_chan_info);
152	    if (ret != DRV_ERROR_NONE) {
153	        PROF_ERR("Failed to write remote r_ptr. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
154	    }
155	
156	    return read_len;
157	}
