168	static drvError_t prof_urma_chan_report(uint32_t dev_id, uint32_t chan_id, void *data, uint32_t data_len, char *priv)
169	{
170	    struct prof_urma_chan_priv *chan_priv = (struct prof_urma_chan_priv *)priv;
171	    struct prof_adapt_core_notifier *notifier = prof_adapt_get_notifier();
172	    struct prof_urma_chan_info *urma_chan_info = NULL;
173	    uint32_t new_wptr = *((uint32_t *)data);
174	    uint32_t old_wptr;
175	
176	    (void)data_len;
177	
178	    old_wptr = prof_buff_get_writeptr(chan_priv->buff);
179	    if (new_wptr != old_wptr) {
180	        prof_buff_update_writeptr(chan_priv->buff, new_wptr);
181	        notifier->poll_report(dev_id, chan_id);
182	    }
183	
184	    urma_chan_info = chan_priv->urma_chan_info;
185	
186	    return prof_urma_post_recv(urma_chan_info, 1);
187	}
