190	    .init = prof_urma_chan_init,
191	    .uninit = prof_urma_chan_uninit,
192	    .start = prof_urma_chan_start,
193	    .stop = prof_urma_chan_stop,
194	    .flush = prof_urma_chan_flush,
195	    .read = prof_urma_chan_read,
196	    .query = prof_urma_chan_query,
197	    .report = prof_urma_chan_report,
198	};
