        PROF_ERR("Failed get process sign. (devid=%u, ret=%d).\n", dev_id, (int)ret);
        return ret;
    }

    ret = halGetDeviceInfo(dev_id, MODULE_TYPE_SYSTEM, INFO_TYPE_HD_CONNECT_TYPE, &h2d_type);
