    if (h2d_type == HOST_DEVICE_CONNECT_TYPE_UB) {
        if (urma_ops->get_channels == NULL) {
            PROF_ERR("Failed to get urma ops. (dev_id=%u)\n", dev_id);
            return DRV_ERROR_INNER_ERR;
