42	    uint32_t sample_buff_size;
43	    struct prof_sample_ops ops;
44	    struct prof_sample_ops ops_ex;
45	    /* The timer callback is processed asynchronously,
46	     * so it is necessary to ensure that the semaphore memory is always available */
47	    sem_t sem;
