52	STATIC drvError_t prof_user_chan_add(uint32_t dev_id, uint32_t chan_id, struct prof_sample_register_para *para, bool support_host_sample)
53	{
54	    struct prof_user_chan_node *node = NULL;
55	    struct list_head *pos = NULL, *n = NULL;
56	    struct prof_sample_ops *ops;
57	
58	    (void)pthread_mutex_lock(&g_chan_list_mutex);
59	    list_for_each_safe(pos, n, &g_prof_user_chan_list) {
60	        node = list_entry(pos, struct prof_user_chan_node, list_node);
61	        if ((node->dev_id == dev_id) && (node->chan_id == chan_id)) {
62	            if (support_host_sample) {
63	                ops = &node->ops_ex;
64	                node->sample_buff_size = 512 * 1024; /* 512 1024: 512K*/
65	            } else {
66	                ops = &node->ops;
67	            }
68	            ops->start_func = para->ops.start_func;
69	            ops->sample_func = para->ops.sample_func;
70	            ops->flush_func = para->ops.flush_func;
71	            ops->stop_func = para->ops.stop_func;
72	            (void)pthread_mutex_unlock(&g_chan_list_mutex);
73	            return DRV_ERROR_NONE;
74	        }
75	    }
76	
77	    node = (struct prof_user_chan_node *)malloc(sizeof(*node));
78	    if (node == NULL) {
79	        (void)pthread_mutex_unlock(&g_chan_list_mutex);
80	        PROF_ERR("Failed to alloc chan_node. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
81	        return DRV_ERROR_MALLOC_FAIL;
82	    }
83	    node->dev_id = dev_id;
84	    node->chan_id = chan_id;
85	    node->sample_buff_size = 0;
86	    if (support_host_sample) {
87	        ops = &node->ops_ex;
88	        node->sample_buff_size = 512 * 1024; /* 512 1024: 512K*/
89	    } else {
90	        ops = &node->ops;
91	    }
92	    ops->start_func = para->ops.start_func;
93	    ops->sample_func = para->ops.sample_func;
94	    ops->flush_func = para->ops.flush_func;
95	    ops->stop_func = para->ops.stop_func;
96	    drv_user_list_add_tail(&node->list_node, &g_prof_user_chan_list);
97	
98	    (void)pthread_mutex_unlock(&g_chan_list_mutex);
99	
100	    return DRV_ERROR_NONE;
101	}
