108	    (void)pthread_mutex_lock(&g_chan_list_mutex);
109	    list_for_each_safe(pos, n, &g_prof_user_chan_list) {
110	        node = list_entry(pos, struct prof_user_chan_node, list_node);
111	        if ((node->dev_id == dev_id) && (node->chan_id == chan_id)) {
112	            drv_user_list_del(&node->list_node);
