357	STATIC void *prof_user_sample_thread(void *arg)
358	{
359	    (void)prctl(PR_SET_NAME, "prof_sample");
360	    struct prof_user_chan_priv *chan_priv = (struct prof_user_chan_priv *)arg;
361	    struct prof_adapt_core_notifier *notifier = prof_adapt_get_notifier();
362	    struct prof_sample_para para = {0};
363	    uint32_t dev_id = chan_priv->dev_id;
364	    uint32_t chan_id = chan_priv->chan_id;
365	    uint32_t buff_len = 100 * 1024;    /* 100 * 1024 Byte */
366	    uint8_t *buff;
367	    int ret;
368	
369	    PROF_INFO("Sample thread start. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
370	    if (chan_priv->support_host_sample) {
371	        buff_len = chan_priv->sample_buff_size;
372	        if (buff_len == 0) {
373	            PROF_ERR("Invalid buff len. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
374	            return NULL;
375	        }
376	    }
377	
378	    buff = (uint8_t *)malloc(buff_len);
379	    if (buff == NULL) {
380	        PROF_ERR("Failed to malloc buff mem. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
381	        return NULL;
382	    }
383	
384	    para.sample_flag = SAMPLE_DATA_WITH_HEADER;
385	    while (chan_priv->sample_thread_flag) {
386	        (void)sem_wait(chan_priv->sem);
387	
388	        (void)CAS(&chan_priv->sample_status, PROF_SAMPLE_FLUSH_START, PROF_SAMPLE_FLUSH_STARTING);
389	        para.dev_id = dev_id;
390	        para.target_pid = getpid();
391	        para.buff = buff;
392	        para.buff_len = buff_len;
393	        para.report_len = 0;
394	        ret = chan_priv->ops.sample_func(&para);
395	        if (ret == DRV_ERROR_CALL_NO_RETRY) {
396	            (void)CAS(&chan_priv->sample_status, PROF_SAMPLE_FLUSH_STARTING, PROF_SAMPLE_FLUSH_FINISH);
397	            break;
398	        }
399	
400	        if ((ret != 0) || (para.report_len > buff_len)) {
401	            (void)CAS(&chan_priv->sample_status, PROF_SAMPLE_FLUSH_STARTING, PROF_SAMPLE_FLUSH_FINISH);
402	            continue;
403	        }
404	
405	        if (para.report_len != 0) {
406	            (void)notifier->chan_report(dev_id, chan_id, para.buff, para.report_len, false);
407	        }
408	
409	        para.sample_flag = SAMPLE_DATA_ONLY;
410	        (void)CAS(&chan_priv->sample_status, PROF_SAMPLE_FLUSH_STARTING, PROF_SAMPLE_FLUSH_FINISH);
411	    }
412	
413	    free(buff);
414	
415	    PROF_INFO("Sample thread exit. (dev_id=%u, chan_id=%u)\n", dev_id, chan_id);
416	    return NULL;
417	}
