425	
426	    (void)pthread_attr_init(&attr);
427	    (void)pthread_attr_setscope(&attr, PTHREAD_SCOPE_SYSTEM);
428	    ret = pthread_create(&chan_priv->sample_thread, &attr, prof_user_sample_thread, chan_priv);
429	    if (ret != 0) {
430	        chan_priv->sample_thread_flag = 0;
431	        PROF_ERR("Failed to create the sample thread. (ret=%d)\n", ret);
432	        return DRV_ERROR_INNER_ERR;
433	    }
434	    (void)pthread_attr_destroy(&attr);
435	
436	    return DRV_ERROR_NONE;
437	}
