452	STATIC void  prof_user_sample_timer_handle(union sigval v)
453	{
454	    sem_t *sem = (sem_t *)v.sival_ptr;
455	    (void)sem_post(sem);
456	}
457	
458	drvError_t prof_user_sample_timer_init(struct prof_user_chan_priv *chan_priv, uint32_t sample_period)
459	{
460	    struct sigevent sig_ev = {0};
461	    struct itimerspec ts;
462	    int ret;
463	
464	    sig_ev.sigev_value.sival_ptr = chan_priv->sem;
465	    sig_ev.sigev_notify = SIGEV_THREAD;
466	    sig_ev.sigev_notify_function = prof_user_sample_timer_handle;
467	    ret = timer_create(CLOCK_MONOTONIC, &sig_ev, &chan_priv->timer_fd);
468	    if (ret != 0) {
469	        PROF_ERR("Failed to create timer. (ret=%d)\n", ret);
470	        return DRV_ERROR_INNER_ERR;
471	    }
472	
473	    ts.it_interval.tv_sec = sample_period / 1000;   /* 1000ms = 1s */
474	    ts.it_interval.tv_nsec = (sample_period % 1000) * 1000000; /* 1000ms = 1s 1000000ns = 1ms */
475	    ts.it_value.tv_sec = ts.it_interval.tv_sec;
476	    ts.it_value.tv_nsec = ts.it_interval.tv_nsec;
477	    ret = timer_settime(chan_priv->timer_fd, 0, &ts, NULL);
478	    if (ret != 0) {
479	        (void)timer_delete(chan_priv->timer_fd);
480	        PROF_ERR("Failed to set timer. (ret=%d)\n", ret);
481	        return DRV_ERROR_INNER_ERR;
482	    }
483	
484	    return DRV_ERROR_NONE;
485	}
486	
487	void prof_user_sample_timer_uninit(struct prof_user_chan_priv *chan_priv)
488	{
489	    int ret;
490	
491	    /* Non-periodic sampling */
492	    if (chan_priv->timer_fd == NULL) {
493	        return;
494	    }
495	
496	    ret = timer_delete(chan_priv->timer_fd);
497	    if (ret != 0) {
498	        PROF_ERR("Failed to delete timer. (ret=%d)\n", ret);
499	    }
500	    chan_priv->timer_fd = NULL;
501	}
502	
503	STATIC drvError_t prof_user_chan_start(uint32_t dev_id, uint32_t chan_id, struct prof_user_start_para *para,
504	    char *priv)
505	{
506	    struct prof_user_chan_priv *chan_priv = (struct prof_user_chan_priv *)priv;
507	    drvError_t ret;
508	    struct prof_start_event_out_msg start_out_msg = {0};
509	
510	    ret = prof_user_sample_start_check(chan_priv, para);
511	    if (ret != DRV_ERROR_NONE) {
512	        PROF_ERR("Failed to check para. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
513	        return ret;
514	    }
515	
516	    ret = prof_user_sample_start(chan_priv, para, &start_out_msg, false);
517	    if (ret != DRV_ERROR_NONE) {
518	        PROF_ERR("Failed to start user sample. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
519	        return ret;
520	    }
521	
522	    /* Non-periodic sampling */
523	    if (para->sample_period == 0) {
524	        return DRV_ERROR_NONE;
525	    }
526	
527	    ret = prof_user_sample_thread_enable(chan_priv);
528	    if (ret != DRV_ERROR_NONE) {
529	        prof_user_sample_stop(chan_priv, PROF_STOP_STAGE_DEFAULT);
530	        PROF_ERR("Failed to enable thread. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
531	        return ret;
532	    }
533	
534	    ret = prof_user_sample_timer_init(chan_priv, para->sample_period);
535	    if (ret != DRV_ERROR_NONE) {
536	        prof_user_sample_thread_disable(chan_priv);
537	        prof_user_sample_stop(chan_priv, PROF_STOP_STAGE_DEFAULT);
538	        PROF_ERR("Failed to init timer. (dev_id=%u, chan_id=%u, ret=%d)\n", dev_id, chan_id, (int)ret);
539	        return ret;
540	    }
541	
542	    return DRV_ERROR_NONE;
543	}
544	
545	drvError_t prof_user_chan_stop(uint32_t dev_id, uint32_t chan_id, struct prof_user_stop_para *para,
546	    char *priv)
547	{
548	    (void)para;
549	    struct prof_user_chan_priv *chan_priv = (struct prof_user_chan_priv *)priv;
550	
551	    prof_user_sample_timer_uninit(chan_priv);
552	    prof_user_sample_thread_disable(chan_priv);
553	    prof_user_sample_stop(chan_priv, para->host_sample_release_flag);
554	
555	    if (chan_priv->sample_mode == PROF_SAMPLE_LOCAL_MODE) {
556	        prof_buff_wait_read_empty(chan_priv->buff, dev_id, chan_id);
557	    }
558	
559	    return DRV_ERROR_NONE;
560	}
561	
562	STATIC drvError_t prof_user_chan_flush(uint32_t dev_id, uint32_t chan_id, uint32_t *data_len, char *priv)
563	{
564	    (void)dev_id;
565	    (void)chan_id;
566	    struct prof_user_chan_priv *chan_priv = (struct prof_user_chan_priv *)priv;
567	
568	    if (chan_priv->sample_mode == PROF_SAMPLE_LOCAL_MODE) {
569	        *data_len = prof_buff_get_data_len(chan_priv->buff);
570	        return DRV_ERROR_NONE;
571	    } else {
572	        return DRV_ERROR_NOT_SUPPORT;
573	    }
574	}
575	
576	int prof_user_chan_read(uint32_t dev_id, uint32_t chan_id, prof_user_read_para_t *read_para, char *priv)
577	{
578	    (void)dev_id;
579	    (void)chan_id;
580	    struct prof_user_chan_priv *chan_priv = (struct prof_user_chan_priv *)priv;
581	
582	    if (chan_priv->sample_mode == PROF_SAMPLE_LOCAL_MODE) {
583	        return prof_buff_read(chan_priv->buff, read_para->out_buf, read_para->buf_size);
584	    } else {
585	        return 0;
586	    }
587	}
588	
589	STATIC drvError_t prof_user_chan_query(uint32_t dev_id, uint32_t chan_id, uint32_t *avail_len, char *priv)
590	{
591	    struct prof_user_chan_priv *chan_priv = (struct prof_user_chan_priv *)priv;
592	    struct prof_user_kernel_ops *kernel_ops = NULL;
593	    drvError_t ret;
594	
595	    if (chan_priv->sample_mode == PROF_SAMPLE_LOCAL_MODE) {
596	        *avail_len = prof_buff_get_avail_len(chan_priv->buff);
597	        return DRV_ERROR_NONE;
598	    }
599	
600	    kernel_ops = prof_user_get_kernel_ops();
601	    if (kernel_ops->chan_query != NULL) {
602	        ret = kernel_ops->chan_query(dev_id, chan_id, avail_len);
603	        if (ret != DRV_ERROR_NONE) {
604	            PROF_ERR("Failed to query avail_len from kernel. (dev_id=%u, chan_id=%u, ret=%d)\n",
605	                dev_id, chan_id, (int)ret);
606	            return ret;
607	        }
608	    }
609	
610	    return DRV_ERROR_NONE;
611	}
612	
613	drvError_t prof_user_chan_report(uint32_t dev_id, uint32_t chan_id, void *data, uint32_t data_len,
614	    char *priv)
615	{
616	    struct prof_user_chan_priv *chan_priv = (struct prof_user_chan_priv *)priv;
617	    struct prof_adapt_core_notifier *notifier = NULL;
618	    struct prof_user_kernel_ops *kernel_ops = NULL;
619	    drvError_t ret;
620	
621	    if (chan_priv->sample_mode == PROF_SAMPLE_LOCAL_MODE) {
622	        ret = prof_buff_write(chan_priv->buff, data, data_len);
623	        if (ret != DRV_ERROR_NONE) {
624	            PROF_ERR("Failed to write data to local buff. (dev_id=%u, chan_id=%u, data_len=%u, ret=%d)\n",
625	                dev_id, chan_id, data_len, (int)ret);
626	            return ret;
627	        }
628	
629	        notifier = prof_adapt_get_notifier();
630	        notifier->poll_report(dev_id, chan_id);
631	        return DRV_ERROR_NONE;
632	    }
633	
634	    kernel_ops = prof_user_get_kernel_ops();
635	    if (kernel_ops->chan_writer != NULL) {
636	        ret = kernel_ops->chan_writer(dev_id, chan_id, data, data_len);
637	        if (ret != DRV_ERROR_NONE) {
638	            PROF_ERR("Failed to write data to kernel. (dev_id=%u, chan_id=%u, data_len=%u, ret=%d)\n",
639	                dev_id, chan_id, data_len, (int)ret);
640	            return ret;
641	        }
642	    }
643	
644	    return DRV_ERROR_NONE;
645	}
646	
647	static struct prof_chan_ops prof_user_chan_ops = {
648	    .init = prof_user_chan_init,
649	    .uninit = prof_user_chan_uninit,
650	    .start = prof_user_chan_start,
651	    .stop = prof_user_chan_stop,
652	    .flush = prof_user_chan_flush,
653	    .read = prof_user_chan_read,
654	    .query = prof_user_chan_query,
655	    .report = prof_user_chan_report,
656	};
657	
