191	drvError_t prof_chan_stop(uint32_t dev_id, uint32_t chan_id, struct prof_user_stop_para *para, bool event_flag)
192	{
193	    struct prof_chan_mng *chan_mng = NULL;
194	    drvError_t ret;
195	
196	    chan_mng = prof_chan_get_mng(dev_id, chan_id);
